import {expenseOverview,advancesByPerson,expenseScopes,expenseUses} from './expense-attribution-model.mjs';
import {money,cents} from './management-model.mjs';
import {chinaDate} from './cloud-contract.mjs';
export function renderExpenseLedger({data,h,heading,canMaintain}){
 const $=s=>document.querySelector(s),people=advancesByPerson(data),total=people.reduce((n,p)=>n+cents(p.totalCents),0n),paid=data.payments.reduce((n,p)=>n+cents(p.amountCents),0n);
 $('#main').innerHTML=heading('记账本','记录日常支出，核对费用归属和每个人的待报销金额。')+`<section class="summary-strip"><div><b>${h(money(total.toString()))}</b><span>累计待报销</span></div><div><b>${h(money(paid.toString()))}</b><span>累计已报销</span></div></section>
  <section class="work-panel module-panel"><div class="panel-head"><h2>待报销 · 按人汇总</h2><a class="text-button" href="#settlements">进入结算与报销</a></div><p class="muted">累计余额跨月保留，不随支出筛选变化。</p>${people.map(p=>`<div class="balance-row"><span><b>${h(p.payerName)}</b><small>未纳入结算 ${h(money(p.unassignedCents))} · 结算后未付 ${h(money(p.inStatementsCents))}</small></span><b>${h(money(p.totalCents))}</b></div>`).join('')||'<p class="muted">当前没有待报销垫付。</p>'}</section>
  <section class="work-panel module-panel"><div class="module-toolbar">${canMaintain?'<button class="primary" data-edit-expense="">＋ 记录支出</button>':''}<button class="secondary" data-studio-overview="">经营总览</button><button class="secondary" data-finance-closing="">财务月结</button><button class="secondary" data-finance-review="">月度来源检查</button><button class="secondary" data-cash-list>实际到账与付款</button><label>发生月份<input id="finance-month" type="month" value="${h(chinaDate().slice(0,7))}"></label><label>付款方式<select id="finance-mode"><option value="all">全部</option><option value="advance">个人垫付</option><option value="company">公司支付</option></select></label><label>归属<select id="finance-scope"><option value="all">全部</option><option value="public">工作室公共</option><option value="store">店铺专属</option><option value="pending">待核对</option></select></label><label class="module-search">查找支出<input id="finance-query" type="search" placeholder="事项、垫付人或店铺"></label></div><div id="finance-overview"></div><div id="finance-body"></div>
  <details class="finance-categories"><summary>经营与成本明细</summary><div class="action-row"><button class="secondary" data-sample-cost-list>样品资产与损耗</button><button class="secondary" data-inventory-cost-list>包材成本与其他出库归属</button><button class="secondary" data-operating-list>销售、退款与手续费</button><button class="secondary" data-cost-catalog="0">已售成本核对</button><button class="secondary" data-dropship-list="0">代发成本批次</button></div></details>
  ${canMaintain?`<details class="finance-categories"><summary>维护支出分类</summary><button class="secondary" data-expense-category>新增分类</button><div class="action-row">${data.categories.map(c=>`<button class="secondary" data-expense-category="${h(c.id)}">${h(c.name)} · ${c.active?'启用':'停用'}</button>`).join('')}</div></details>`:''}<p class="muted">公共费用只在工作室层面汇总，报销不再次计入费用。经营利润以经营总览为准，平台已扣项目在总览中排除重复扣减。</p></section>`;
 function render(){
  const month=$('#finance-month').value,mode=$('#finance-mode').value,scope=$('#finance-scope').value,q=$('#finance-query').value.trim().toLowerCase();
  const period=data.records.filter(r=>!month||r.expenseDate?.startsWith(month)),o=expenseOverview(period);
  $('#finance-overview').innerHTML=`<h3>${month?h(month):'全部期间'} · 费用归属概览</h3><p class="muted">按所选月份的全部支出汇总，不随下方付款方式、归属或关键词筛选变化。</p><section class="summary-strip"><div><b>${h(money(o.publicCents))}</b><span>公共运营费用</span></div><div><b>${h(money(o.directCents))}</b><span>店铺专属运营费用合计</span></div><div><b>${h(money(o.pendingCents))}</b><span>待核对 · ${o.pendingCount} 笔</span></div></section><p>库存采购 ${h(money(o.inventoryCents))} · 预付款项 ${h(money(o.prepaidCents))}，单独列示。</p>${o.stores.map(s=>`<div class="balance-row"><span>${h(s.storeName)} · 专属运营费用</span><b>${h(money(s.amountCents))}</b></div>`).join('')}<p class="muted">商品已售成本、包材消耗、收入及利润仍按各自来源核对。待核对金额不计入已确认运营费用。</p>`;
  const pending=r=>!r.expenseScope||r.expenseScope==='unclassified'||!r.expenseUse||r.expenseUse==='unclassified';
  const rows=period.filter(r=>(mode==='all'||r.paymentMode===mode)&&(scope==='all'||scope==='pending'&&pending(r)||r.expenseScope===scope)&&[r.description,r.payerName,r.storeName].join(' ').toLowerCase().includes(q));
  const sum=rows.reduce((n,r)=>n+cents(r.amountCents),0n).toString();
  $('#finance-body').innerHTML=`<p class="muted">${rows.length} 笔 · 本筛选支出发生额 ${h(money(sum))}</p><div class="table-scroll"><table class="record-table"><thead><tr><th>支出事项</th><th>日期</th><th>用途 / 归属</th><th>付款方式</th><th>金额</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-title" data-manage-open="${h(r.id)}">${h(r.description)}</button></td><td>${h(r.expenseDate)}</td><td>${h(expenseUses[r.expenseUse||'unclassified'])}<p>${h(expenseScopes[r.expenseScope||'unclassified'])}${r.storeName?' · '+h(r.storeName):''} · ${h(r.categoryName||'未分类')}</p>${canMaintain&&pending(r)?`<button class="text-button" data-expense-attribution="${h(r.id)}">核对用途与归属</button>`:''}</td><td>${h(r.paymentMode==='advance'?'垫付 · '+(r.payerName||'原垫付人'):'公司支付')}</td><td class="money-cell">${h(money(r.amountCents))}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<p class="muted">暂无符合筛选的支出。</p>'}`;
 }
 for(const id of ['#finance-month','#finance-mode','#finance-scope'])$(id).onchange=render;$('#finance-query').oninput=render;render();
}
